        DB::table('StudentClass')
            ->where('ID', $courseId)
            ->update(['EndDate' => $extendedEndDate]);
    }

    $rows = $this->fetchCourseSessionRows($courseId);

    return [$rows, $extendedEndDate, $leaveSessionDate];
}

