    /**
     * Toggle pause/resume for a student course.
     * Pause: sets Stop=1 and cancels future scheduled sessions.
     * Resume: sets Stop=0.
     */
    public function togglePause(Request $request, $studentClass)
    {
        $sc = StudentClass::find($studentClass);
        if (!$sc) {
            return response()->json(['message' => '找不到課程'], 404);
        }

        $action = $request->input('action', 'pause');
        $today = Carbon::today()->toDateString();

        DB::beginTransaction();
        try {
            if ($action === 'pause') {
                $sc->Stop = 1;
                $sc->save();

                $cancelled = ClassSession::where('StudentClassID', $sc->ID)
                    ->where('SessionDate', '>=', $today)
                    ->where('Status', 'scheduled')
                    ->update([
                        'Status' => 'cancelled',
                        'Note' => DB::raw("CONCAT(COALESCE(Note,''), ' [暫停取消]')"),
                        'updated_at' => now(),
                    ]);

                DB::commit();
                return response()->json([
                    'message' => "課程已暫停，已取消 {$cancelled} 堂未來排課。",
                    'cancelled_count' => $cancelled,
                ]);
            } else {
                $sc->Stop = 0;
                $sc->save();

                DB::commit();
                return response()->json([
                    'message' => '課程已恢復，可重新排課。',
                ]);
            }
        } catch (\Throwable $e) {
            DB::rollBack();
            return response()->json(['message' => '操作失敗：' . $e->getMessage()], 500);
        }
    }
}

